params.command:
$ErrorActionPreference='Stop'
$repo='C:\Users\Xxkan\local-ai-workspaces\mhw-mods'
$expected=[ordered]@{
  'fix/heaven-default-routing-20260929'='b38b171e8a1a63a3fc0dfd6cae0d2621285afe98'
  'fix/updater-bom-release-closure-20260929'='d9ca6aff0b26ce4cc21bd794bd500d0fce8c7ad4'
  'fix/updater-e2e-heaven-runner-20260929'='5913d4a3385c1b862e673f7dee68e49275a0fb0e'
  'fix/updater-e2e-latest-release-20260929'='4f9d40e9c9616b46b2ca93117af9f7fc84637673'
  'fix/updater-final-closure-20260929'='a8007d22281e43498b615f918be1804cd49793f2'
  'fix/updater-heaven-routing-20260929'='61e9fd266746f4e0c4ca5f28b65ffd8f88107e28'
  'fix/updater-release-heaven-closure-20260929'='83fec76cb908b78b7c58192e61a44956eae6fb01'
}
git -C $repo fetch origin --prune
$deleted=@(); $skipped=@()
foreach($b in $expected.Keys){
  $line=(git -C $repo ls-remote origin "refs/heads/$b")
  if(-not $line){$skipped += [pscustomobject]@{branch=$b;reason='already-absent'}; continue}
  $actual=(($line.Trim()) -split '\s+')[0]
  if($actual -ne $expected[$b]){$skipped += [pscustomobject]@{branch=$b;reason='tip-moved';expected=$expected[$b];actual=$actual}; continue}
  $open=(gh pr list --repo fengie/mhw-mods --state open --head $b --json number --jq 'length')
  if($LASTEXITCODE -ne 0){throw "gh pr list failed for $b"}
  if([int]$open -gt 0){$skipped += [pscustomobject]@{branch=$b;reason='open-pr'}; continue}
  git -C $repo push origin --delete $b
  if($LASTEXITCODE -ne 0){throw "delete failed for $b"}
  $deleted += $b
}
git -C $repo fetch origin --prune
$remaining=@(git -C $repo for-each-ref --format='%(refname:short)' refs/remotes/origin | Where-Object {$_ -notmatch 'origin/HEAD'})
[pscustomobject]@{deleted=$deleted;skipped=$skipped;remaining=$remaining} | ConvertTo-Json -Depth 6
